62	static void parse_args(int argc, FAR char *argv[])
63	{
64	  int opt;
65	
66	  while ((opt = getopt(argc, argv, "r:c:f:d:v:TFMCLh")) != -1)
67	    {
68	      switch (opt)
69	        {
70	          case 'r': g_sample_rate   = atoi(optarg); break;
71	          case 'c': g_channels      = atoi(optarg); break;
72	          case 'f': g_freq_hz       = atoi(optarg); break;
73	          case 'd': g_duration_ms   = atoi(optarg); break;
74	          case 'v': g_volume        = atoi(optarg); break;
75	          case 'T': g_trace_mode    = 1;            break;
76	          case 'F': g_fifo_cpu_mode = 1;            break;
77	          case 'M': g_mclk_mode     = 1;            break;
78	          case 'C': g_capture_mode  = 1;            break;
79	          case 'L': g_loop_mode     = 1;            break;
80	          case 'h':
81	          default:  usage(argv[0]);
82	        }
83	    }
84	}
