86	/* Fill an S16_LE buffer with a bounded sine wave at g_freq_hz.  phase is
87	 * carried across buffers so sample-boundary discontinuities do not create
88	 * audible clicks.
89	 */
90	
91	static void fill_sine(FAR int16_t *dst, size_t nsamples,
92	                      FAR double *phase)
93	{
94	  const double step = 2.0 * M_PI * g_freq_hz / (double)g_sample_rate;
95	  const int16_t amp = 20000;   /* headroom below full-scale.            */
96	  size_t i;
97	
98	  for (i = 0; i < nsamples; i += g_channels)
99	    {
100	      int16_t s = (int16_t)(amp * sin(*phase));
101	      int c;
102	
103	      for (c = 0; c < g_channels; c++)
104	        {
105	          dst[i + c] = s;
106	        }
107	
108	      *phase += step;
109	      if (*phase >= 2.0 * M_PI)
110	        {
111	          *phase -= 2.0 * M_PI;
112	        }
113	    }
114	}
