116	static int set_volume(int fd, int volume)
117	{
118	  struct audio_caps_desc_s cap;
119	
120	  memset(&cap, 0, sizeof(cap));
121	  cap.caps.ac_len            = sizeof(struct audio_caps_s);
122	  cap.caps.ac_type           = AUDIO_TYPE_FEATURE;
123	  cap.caps.ac_format.hw      = AUDIO_FU_VOLUME;
124	  cap.caps.ac_controls.hw[0] = (uint16_t)volume;
125	  return ioctl(fd, AUDIOIOC_CONFIGURE, (unsigned long)&cap);
126	}
