333	  if (g_mclk_mode)
334	    {
335	      /* Software observation route: mux I2S1_MCLK onto GPIO28 so the audio
336	       * functional clock (XTAL 26 MHz vs APLL ~98.304 MHz) can be measured
337	       * with a scope on the P28 pad.  This answers "is the audio clock
338	       * domain actually oscillating?" independent of the known-dead
339	       * FIFO/DREQ data path.
340	       */
341	
342	      static const char *const clk_name[] = {"XTAL", "APLL"};
343	      volatile uint32_t *p_gpio28_cfg =
344	        (volatile uint32_t *)0x44000470u;   /* GPIO_CFG(28)       */
345	      volatile uint32_t *p_func28 =
346	        (volatile uint32_t *)0x440100ccu;   /* SYS_GPIO_FUNC(28)  */
347	      volatile uint32_t *p_clkdiv1 =
348	        (volatile uint32_t *)0x44010020u;   /* SYS_CLK_DIV_MODE1  */
349	      volatile uint32_t *p_clkdiv2 =
350	        (volatile uint32_t *)0x44010024u;   /* SYS_CLK_DIV_MODE2  */
351	      volatile uint32_t *p_devclk =
352	        (volatile uint32_t *)0x44010030u;   /* DEVICE_CLK_EN[0xc] */
353	      volatile uint32_t *p_devclk2 =
354	        (volatile uint32_t *)0x44010034u;   /* DEVICE_CLK_EN[0xd] */
355	      struct bk7258_dac_cfg_s dac_cfg;
356	
357	      /* Mux GPIO28 -> I2S1_MCLK (AF2): per-pin cfg mode=DIS + second-func
358	       * (bit-identical to bk7258_gpio_periph(28, 1)); SYS_GPIO_FUNC field
359	       * bits[19:16] = 1. */
360	      *p_gpio28_cfg = (*p_gpio28_cfg & ~UINT32_C(0x3c)) | UINT32_C(0x48);
361	      *p_func28     = (*p_func28     & ~UINT32_C(0x000f0000)) |
362	                      UINT32_C(0x00010000);
363	
364	      /* Gate on the I2S + I2S1 functional clocks. */
365	      *p_devclk  |= UINT32_C(1) << 16;   /* i2s_cken  */
366	      *p_devclk2 |= UINT32_C(1) << 1;    /* i2s1_cken */
367	
368	      dac_cfg.samp_rate = (uint32_t)g_sample_rate;
369	      dac_cfg.channel   = BK7258_DAC_CHL_LR;
370	      dac_cfg.work_mode = BK7258_DAC_WORK_DIFFEN;
371	      dac_cfg.gain      = 0;
372	
373	      ret = bk7258_aud_subsystem_init();
374	      if (ret < 0)
375	        {
376	          fprintf(stderr, "[bk] MCLK subsystem init failed: %d\n", ret);
377	          goto cleanup;
378	        }
379	
380	      for (int phase = 0; phase < 2; phase++)
381	        {
382	          uint32_t sel = phase != 0;
383	
384	          bk7258_dac_reset_data_path();
385	          dac_cfg.use_apll = sel != 0;
386	          ret = bk7258_dac_configure(&dac_cfg);
387	          if (ret < 0)
388	            {
389	              fprintf(stderr, "[bk] MCLK %s configure failed: %d\n",
390	                      clk_name[phase], ret);
391	              bk7258_dac_deinit();
392	              goto cleanup;
393	            }
394	
395	          /* Point I2S / I2S1 MCLK at the same functional clock:
396	           * cksel_i2s (bit24) + cksel_i2s1 (bit11). 0=XTAL(26M) 1=APLL. */
397	          if (sel)
398	            {
399	              *p_clkdiv1 |= UINT32_C(1) << 24;
400	              *p_clkdiv2 |= UINT32_C(1) << 11;
401	            }
402	          else
403	            {
404	              *p_clkdiv1 &= ~(UINT32_C(1) << 24);
405	              *p_clkdiv2 &= ~(UINT32_C(1) << 11);
406	            }
407	
408	          printf("[bk] MCLK phase=%s cksel_i2s=%lu cksel_i2s1=%lu "
409	                 "cksel_aud=%lu clkdiv1=%08lx clkdiv2=%08lx\n",
410	                 clk_name[phase],
411	                 (unsigned long)((*p_clkdiv1 >> 24) & 1),
412	                 (unsigned long)((*p_clkdiv2 >> 11) & 1),
413	                 (unsigned long)((*p_clkdiv1 >> 25) & 1),
414	                 (unsigned long)*p_clkdiv1,
415	                 (unsigned long)*p_clkdiv2);
416	          printf("[bk] MCLK -> measure GPIO28 (P28 pad): expect %s\n",
417	                 sel ? "~98.304 MHz (APLL)" : "~26 MHz (XTAL)");
418	          fflush(stdout);
419	          usleep(3000000);
420	        }
421	
422	      bk7258_dac_deinit();
423	      printf("[bk] MCLK done\n"); fflush(stdout);
424	      ret = 0;
425	      goto cleanup;
426	    }
