428	  if (g_capture_mode)
429	    {
430	      /* ADC capture clock detector.  The DAC FIFO never accepts writes, so
431	       * the open question is whether the audio functional clock reaches the
432	       * FIFO at all.  The ADC has an independent FIFO (ADCL): after
433	       * bk7258_adc_start() the capture clock fills it.  If
434	       * bk7258_adc_fifo_empty() clears and real samples appear, the clock IS
435	       * running and the DAC fault is in the DAC write path; if ADCL stays
436	       * empty, the clock is dead at the source.  Runs both XTAL and APLL to
437	       * match the -F DAC probe. */
438	
439	      static const char *const clk_name[] = {"XTAL", "APLL"};
440	      struct bk7258_adc_cfg_s   adc_cfg;
441	      struct bk7258_adc_stats_s snap[2][2];
442	
443	      adc_cfg.samp_rate = (uint32_t)g_sample_rate;
444	      adc_cfg.channel   = BK7258_ADC_CHL_LR;
445	      adc_cfg.gain      = 0x2D;
446	      adc_cfg.samp_edge = false;
447	
448	      ret = bk7258_aud_subsystem_init();
449	      if (ret < 0)
450	        {
451	          fprintf(stderr, "[bk] ADC subsystem init failed: %d\n", ret);
452	          goto cleanup;
453	        }
454	
455	      for (int phase = 0; phase < 2; phase++)
456	        {
457	          uint32_t empty   = 0;
458	          uint32_t filled  = 0;
459	          uint32_t reads   = 0;
460	          uint32_t nonzero = 0;
461	
462	          adc_cfg.use_apll = phase != 0;
463	          ret = bk7258_adc_configure(&adc_cfg);
464	          if (ret < 0)
465	            {
466	              fprintf(stderr, "[bk] ADC %s configure failed: %d\n",
467	                      clk_name[phase], ret);
468	              bk7258_adc_deinit();
469	              goto cleanup;
470	            }
471	
472	          bk7258_adc_start();
473	          bk7258_adc_get_stats(&snap[phase][0]);
474	
475	          for (int t = 0; t < 40; t++)
476	            {
477	              if (bk7258_adc_fifo_empty())
478	                {
479	                  empty++;
480	                }
481	              else
482	                {
483	                  filled++;
484	                  if (bk7258_adc_fifo_read() != 0)
485	                    {
486	                      nonzero++;
487	                    }
488	                  reads++;
489	                }
490	              usleep(5000);
491	            }
492	
493	          bk7258_adc_get_stats(&snap[phase][1]);
494	          bk7258_adc_stop();
495	
496	          printf("[bk] ADC %s empty=%lu filled=%lu reads=%lu nonzero=%lu\n",
497	                 clk_name[phase], (unsigned long)empty,
498	                 (unsigned long)filled, (unsigned long)reads,
499	                 (unsigned long)nonzero);
500	          printf("[bk] ADC %s st0 audio=%08lx adc0=%08lx fifo_cfg=%08lx "
501	                 "fifo_st=%08lx\n",
502	                 clk_name[phase],
503	                 (unsigned long)snap[phase][0].audio_config,
504	                 (unsigned long)snap[phase][0].adc_config0,
505	                 (unsigned long)snap[phase][0].fifo_config,
506	                 (unsigned long)snap[phase][0].fifo_status);
507	          printf("[bk] ADC %s st1 fifo_st=%08lx ext=%08lx clk=%08lx "
508	                 "clk1=%08lx clk2=%08lx dev=%08lx ana18=%08lx ana19=%08lx\n",
509	                 clk_name[phase],
510	                 (unsigned long)snap[phase][1].fifo_status,
511	                 (unsigned long)snap[phase][1].extend_cfg,
512	                 (unsigned long)snap[phase][1].clk_control,
513	                 (unsigned long)snap[phase][1].sys_clk_div_mode1,
514	                 (unsigned long)snap[phase][1].sys_clk_div_mode2,
515	                 (unsigned long)snap[phase][1].device_clk_enable,
516	                 (unsigned long)snap[phase][1].ana_reg18,
517	                 (unsigned long)snap[phase][1].ana_reg19);
518	        }
519	
520	      bk7258_adc_deinit();
521	      fflush(stdout);
522	      ret = 0;
523	      goto cleanup;
524	    }
