149	/* Map upper-half 0..100 volume to a DAC digital-gain register value.
150	 * The endpoints match spec §3: v=0 mutes; v=100 -> AVDK 0 dB default;
151	 * intermediates use a linear ramp for now, replaced by a dB LUT once
152	 * silicon measurement data is available.
153	 */
154	
155	static uint8_t bk7258_volume_to_gain(uint8_t volume)
156	{
157	  if (volume == 0)
158	    {
159	      return 0;
160	    }
161	
162	  if (volume >= 100)
163	    {
164	      return BK7258_AUDIO_MAX_DAC_GAIN;
165	    }
166	
167	  return (uint8_t)(((uint32_t)volume * BK7258_AUDIO_MAX_DAC_GAIN) / 100u);
168	}
