420	        }
421	
422	      bk7258_dac_deinit();
423	      printf("[bk] MCLK done\n"); fflush(stdout);
424	      ret = 0;
425	      goto cleanup;
426	    }
427	
428	  if (g_capture_mode)
429	    {
430	      /* ADC capture clock detector.  The DAC FIFO never accepts writes, so
431	       * the open question is whether the audio functional clock reaches the
432	       * FIFO at all.  The ADC has an independent FIFO (ADCL): after
433	       * bk7258_adc_start() the capture clock fills it.  If
434	       * bk7258_adc_fifo_empty() clears and real samples appear, the clock IS
435	       * running and the DAC fault is in the DAC write path; if ADCL stays
436	       * empty, the clock is dead at the source.  Runs both XTAL and APLL to
437	       * match the -F DAC probe. */
438	
439	      static const char *const clk_name[] = {"XTAL", "APLL"};
440	      struct bk7258_adc_cfg_s   adc_cfg;
441	      struct bk7258_adc_stats_s snap[2][2];
442	
443	      adc_cfg.samp_rate = (uint32_t)g_sample_rate;
444	      adc_cfg.channel   = BK7258_ADC_CHL_LR;
445	      adc_cfg.gain      = 0x2D;
446	      adc_cfg.samp_edge = false;
447	
448	      ret = bk7258_aud_subsystem_init();
449	      if (ret < 0)
450	        {
451	          fprintf(stderr, "[bk] ADC subsystem init failed: %d\n", ret);
452	          goto cleanup;
453	        }
454	
455	      for (int phase = 0; phase < 2; phase++)
456	        {
457	          uint32_t empty   = 0;
458	          uint32_t filled  = 0;
459	          uint32_t reads   = 0;
460	          uint32_t nonzero = 0;
461	
462	          adc_cfg.use_apll = phase != 0;
463	          ret = bk7258_adc_configure(&adc_cfg);
464	          if (ret < 0)
465	            {
466	              fprintf(stderr, "[bk] ADC %s configure failed: %d\n",
467	                      clk_name[phase], ret);
468	              bk7258_adc_deinit();
469	              goto cleanup;
470	            }
471	
472	          bk7258_adc_start();
473	          bk7258_adc_get_stats(&snap[phase][0]);
474	
475	          for (int t = 0; t < 40; t++)
476	            {
477	              if (bk7258_adc_fifo_empty())
478	                {
479	                  empty++;
480	                }
481	              else
482	                {
483	                  filled++;
484	                  if (bk7258_adc_fifo_read() != 0)
485	                    {
486	                      nonzero++;
487	                    }
488	                  reads++;
489	                }
490	              usleep(5000);
491	            }
492	
493	          bk7258_adc_get_stats(&snap[phase][1]);
494	          bk7258_adc_stop();
495	
496	          printf("[bk] ADC %s empty=%lu filled=%lu reads=%lu nonzero=%lu\n",
497	                 clk_name[phase], (unsigned long)empty,
498	                 (unsigned long)filled, (unsigned long)reads,
499	                 (unsigned long)nonzero);
500	          printf("[bk] ADC %s st0 audio=%08lx adc0=%08lx fifo_cfg=%08lx "
501	                 "fifo_st=%08lx\n",
502	                 clk_name[phase],
503	                 (unsigned long)snap[phase][0].audio_config,
504	                 (unsigned long)snap[phase][0].adc_config0,
505	                 (unsigned long)snap[phase][0].fifo_config,
506	                 (unsigned long)snap[phase][0].fifo_status);
507	          printf("[bk] ADC %s st1 fifo_st=%08lx ext=%08lx clk=%08lx "
508	                 "clk1=%08lx clk2=%08lx dev=%08lx ana18=%08lx ana19=%08lx\n",
509	                 clk_name[phase],
510	                 (unsigned long)snap[phase][1].fifo_status,
511	                 (unsigned long)snap[phase][1].extend_cfg,
512	                 (unsigned long)snap[phase][1].clk_control,
513	                 (unsigned long)snap[phase][1].sys_clk_div_mode1,
514	                 (unsigned long)snap[phase][1].sys_clk_div_mode2,
515	                 (unsigned long)snap[phase][1].device_clk_enable,
516	                 (unsigned long)snap[phase][1].ana_reg18,
517	                 (unsigned long)snap[phase][1].ana_reg19);
518	        }
519	
520	      bk7258_adc_deinit();
521	      fflush(stdout);
522	      ret = 0;
523	      goto cleanup;
524	    }
525	
526	  if (g_loop_mode)
527	    {
528	      /* DTMF -> DAC loopback probe.  loop_ton2dac routes the on-chip DTMF
529	       * tone generator straight into the DAC with no host FPORT write.  If a
530	       * tone is audible, the DAC analog path + functional clock are alive and
531	       * the fault is purely in how we feed DAC_FPORT (CPU/GDMA).  If silent,
532	       * the clock/analog bring-up is the fault.  DTMF registers are poked
533	       * bare here (same style as the FPORT-KICK probe) because there is no
534	       * DTMF HAL yet. */
535	
536	      volatile uint32_t *p_dtmf_cfg0 = (volatile uint32_t *)0x478000c4u;
537	      volatile uint32_t *p_dtmf_cfg1 = (volatile uint32_t *)0x478000c8u;
538	      volatile uint32_t *p_dtmf_cfg2 = (volatile uint32_t *)0x478000ccu;
539	      volatile uint32_t *p_audio_cfg = (volatile uint32_t *)0x478000c0u;
540	      struct bk7258_dac_cfg_s dac_cfg;
541	
542	      dac_cfg.samp_rate = (uint32_t)g_sample_rate;
543	      dac_cfg.channel   = BK7258_DAC_CHL_LR;
544	      dac_cfg.work_mode = BK7258_DAC_WORK_DIFFEN;
545	      dac_cfg.gain      = 0;
546	      dac_cfg.use_apll  = false;
547	
548	      ret = bk7258_aud_subsystem_init();
549	      if (ret < 0)
550	        {
551	          fprintf(stderr, "[bk] LOOP subsystem init failed: %d\n", ret);
552	          goto cleanup;
553	        }
554	
555	      ret = bk7258_dac_configure(&dac_cfg);
556	      if (ret < 0)
557	        {
558	          fprintf(stderr, "[bk] LOOP dac configure failed: %d\n", ret);
559	          goto cleanup;
560	        }
561	
562	      ret = bk7258_dac_mute(false);
563	      if (ret < 0)
564	        {
565	          fprintf(stderr, "[bk] LOOP unmute failed: %d\n", ret);
566	          bk7258_dac_deinit();
567	          goto cleanup;
568	        }
569	
570	      bk7258_dac_start();
571	
572	      /* Program the DTMF tone generator: 1 kHz continuous tone.
573	       * tone1_step = F(kHz) * 8191, so 8191 = 1 kHz. */
574	      *p_dtmf_cfg0 = (0u << 0)      /* tone_pattern: DTMF          */
575	                   | (1u << 1)      /* tone_mode: continuous       */
576	                   | (15u << 2)     /* tone_pause_time: 150 ms     */
577	                   | (15u << 6);    /* tone_active_time: 150 ms    */
578	      *p_dtmf_cfg1 = (8191u << 0)   /* tone1_step: 1 kHz           */
579	                   | (0u << 16)     /* tone1_attu: -1 dB           */
580	                   | (1u << 20);    /* tone1_enable                */
581	      *p_dtmf_cfg2 = (8191u << 0)   /* tone2_step: 1 kHz           */
582	                   | (0u << 16)     /* tone2_attu                   */
583	                   | (0u << 20);    /* tone2_enable: off           */
584	
585	      /* dtmf_enable (audio_config bit4), then loop_ton2dac (fifo_config
586	       * bit24). */
587	      *p_audio_cfg |= (1u << 4);
588	      bk7258_aud_loop_ton2dac(true);
589	
590	      printf("[bk] LOOP ton2dac ON — expect a 1 kHz tone for ~3 s\n");
591	      fflush(stdout);
592	      usleep(3000000);
593	
594	      bk7258_aud_loop_ton2dac(false);

1	/****************************************************************************
2	 * chips/bk7258/audio/bk7258_adc.c
3	 *
4	 * BK7258 internal-ADC (analog-MIC capture) register-level HAL.  Public API is
5	 * in bk7258_adc.h.  The bring-up sequence mirrors
6	 * bk_avdk_smp/.../aud_adc_driver.c bk_aud_adc_init() and
7	 * aud_hal.h's register map:
8	 *
9	 *   subsystem init (shared, in bk7258_dac.c) -> clock select -> micen ->
10	 *   adcbias/micbias -> mic reset pulse -> ADC_CONFIG0 digital config ->
11	 *   sample-rate divider.
12	 *
13	 * Derived from Apache-2.0 code in bk_avdk_smp/:
14	 *   - middleware/driver/audio/aud/aud_adc_driver.c
15	 *   - middleware/soc/bk7258_ap/hal/sys_hal.c
16	 *   - middleware/soc/bk7258_ap/hal/aud_ll_macro_def.h
17	 ****************************************************************************/
18	
19	#include <nuttx/config.h>
20	
21	#include <debug.h>
22	#include <errno.h>
23	#include <stdbool.h>
24	#include <stdint.h>
25	
26	#include <nuttx/arch.h>
27	#include <nuttx/irq.h>
28	#include <nuttx/spinlock.h>
29	
30	#include "arm_internal.h"
31	#include "bk7258_internal.h"
32	
33	#include "bk7258_aud_reg.h"
34	#include "bk7258_dac.h"
35	#include "bk7258_adc.h"
36	
37	/****************************************************************************
38	 * Pre-processor Definitions
39	 ****************************************************************************/
40	
41	/* Analog-reg indices shared with the DAC path (see bk7258_dac.c for the
42	 * offset derivation — n is the reg0-relative logical number, also the SPI
43	 * busy-bit number).
44	 */
45	
46	#define BK7258_ANA_REG_APLL_PWD       5    /* ana_reg5, pwdaudpll bit 13. */
47	#define BK7258_ANA_REG18              18
48	#define BK7258_ANA_REG19              19
49	#define BK7258_ANA_REG25_APLL_CFG     25
50	#define BK7258_ANA_REG26_APLL_CAL     26
51	
52	#define ANA_REG5_PWDAUDPLL_BIT        13
53	#define ANA_REG25_SPI_TRIGGER_BIT     18
54	
55	/* Sys ctrl (0x44010000) clock registers/bit positions, taken from
56	 * bk_avdk_smp sys_struct.h for BK7258 (see bk7258_dac.c for full comment).
57	 */
58	
59	#define SYS_CLK_DIV_MODE1             (BK7258_SYS_BASE + (0x8u * 4u))
60	#define   SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT   25
61	#define   SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK  0x1u
62	
63	#define SYS_CLK_DIV_MODE2             (BK7258_SYS_BASE + (0x9u * 4u))
64	#define   SYS_CLK_DIV_MODE2_DMIC_DIV_BIT    13
65	
66	#define SYS_CPU_DEVICE_CLK_EN         (BK7258_SYS_BASE + (0xCu * 4u))
67	#define   SYS_CPU_DEVICE_CLK_AUD_CKEN_BIT   30
68	
69	/* Default ADC-left FIFO write watermark.  AVDK media layer passes this per
70	 * buffer; 8 is a comfortable polled-capture watermark on BK7258.
71	 */
72	
73	#define BK7258_ADC_ADCL_WR_TH_DEFAULT 8u
74	
75	/****************************************************************************
76	 * Private Data
77	 ****************************************************************************/
78	
79	static bool       g_bk7258_adc_configured;
80	static bool       g_bk7258_adc_use_apll;
81	static spinlock_t g_bk7258_adc_lock = SP_UNLOCKED;
82	
83	/****************************************************************************
84	 * Private Helpers
85	 ****************************************************************************/
86	
87	/* These are the same register-access primitives bk7258_dac.c uses.  They are
88	 * `static` in each translation unit (no cross-file symbol), so the identical
89	 * names are deliberate and read consistently across the two HAL files.
90	 */
91	
92	static inline void bk7258_sys_reg_bits(uint32_t addr, uint32_t mask,
93	                                       uint32_t value)
94	{
95	  uint32_t v = getreg32(addr);
96	  v &= ~mask;
97	  v |= (value & mask);
98	  putreg32(v, addr);
99	}
100	
101	static int bk7258_ana_reg_write(uint32_t idx, uint32_t value)
102	{
103	  const uint32_t addr = BK7258_SYS_ANA_REG(idx);
104	  int loops = 1000;
105	
106	  putreg32(value, addr);
107	
108	  while ((getreg32(BK7258_SYS_ANA_SPI_STATE) & (UINT32_C(1) << idx)) != 0)
109	    {
110	      if (--loops <= 0)
111	        {
112	          auderr("BK7258: analog reg %lu SPI wait timeout\n",
113	                 (unsigned long)idx);
114	          return -ETIMEDOUT;
115	        }
116	    }
117	
118	  return OK;
119	}
120	
121	static int bk7258_ana_reg_bit(uint32_t idx, uint32_t pos, uint32_t mask,
122	                              uint32_t value)
123	{
124	  const uint32_t addr = BK7258_SYS_ANA_REG(idx);
125	  uint32_t v = getreg32(addr);
126	
127	  v &= ~(mask << pos);
128	  v |= ((value & mask) << pos);
129	  return bk7258_ana_reg_write(idx, v);
130	}
131	
132	static int bk7258_apll_program(uint32_t cal_val)
133	{
134	  int ret;
135	
136	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG_APLL_PWD,
137	                           ANA_REG5_PWDAUDPLL_BIT, 0x1u, 0);
138	  if (ret < 0)
139	    {
140	      return ret;
141	    }
142	
143	  ret = bk7258_ana_reg_write(BK7258_ANA_REG26_APLL_CAL, cal_val);
144	  if (ret < 0)
145	    {
146	      return ret;
147	    }
148	
149	  ret = bk7258_ana_reg_write(BK7258_ANA_REG25_APLL_CFG,
150	                             BK7258_APLL_CONFIG_VAL);
151	  if (ret < 0)
152	    {
153	      return ret;
154	    }
155	
156	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG25_APLL_CFG,
157	                           ANA_REG25_SPI_TRIGGER_BIT, 0x1u, 1);
158	  if (ret < 0)
159	    {
160	      return ret;
161	    }
162	
163	  up_mdelay(20);
164	
165	  return bk7258_ana_reg_bit(BK7258_ANA_REG25_APLL_CFG,
166	                            ANA_REG25_SPI_TRIGGER_BIT, 0x1u, 0);
167	}
168	
169	/****************************************************************************
170	 * Public Functions
171	 ****************************************************************************/
172	
173	int bk7258_adc_configure(const struct bk7258_adc_cfg_s *cfg)
174	{
175	  irqstate_t flags;
176	  uint32_t v;
177	  int ret;
178	
179	  if (cfg == NULL)
180	    {
181	      return -EINVAL;
182	    }
183	
184	  ret = bk7258_aud_subsystem_init();
185	  if (ret < 0)
186	    {
187	      return ret;
188	    }
189	
190	  g_bk7258_adc_use_apll = cfg->use_apll;
191	
192	  /* Clock select — identical to the DAC configure() clock block; the audio
193	   * clock mux is shared between the DAC and ADC paths.
194	   */
195	
196	  if (cfg->use_apll)
197	    {
198	      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
199	                          SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
200	                              << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
201	                          UINT32_C(1) << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT);
202	
203	      ret = bk7258_apll_program(BK7258_APLL_CAL_VAL_48K);
204	      if (ret < 0)
205	        {
206	          return ret;
207	        }
208	
209	      v = getreg32(BK7258_AUD_AUDIO_CONFIG);
210	      v |= AUD_AUDIO_CFG_APLL_SEL;
211	      putreg32(v, BK7258_AUD_AUDIO_CONFIG);
212	
213	      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE2,
214	                          UINT32_C(1) << SYS_CLK_DIV_MODE2_DMIC_DIV_BIT,
215	                          UINT32_C(1) << SYS_CLK_DIV_MODE2_DMIC_DIV_BIT);
216	    }
217	  else
218	    {
219	      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
220	                          SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
221	                              << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
222	                          0u);
223	
224	      v = getreg32(BK7258_AUD_AUDIO_CONFIG);
225	      v &= ~AUD_AUDIO_CFG_APLL_SEL;
226	      putreg32(v, BK7258_AUD_AUDIO_CONFIG);
227	    }
228	
229	  /* Analog MIC preamp enable.  On BK7258 only micen (ana_reg19[28]) is wired;
230	   * AVDK's mic2_en is a no-op, so dual-MIC shares this one bit.  Order matches
231	   * aud_adc_driver.c: micen -> biases -> reset pulse.
232	   */
233	
234	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG19,
235	                           ANA_REG19_MICEN_BIT, 0x1u, 1);
236	  if (ret < 0)
237	    {
238	      return ret;
239	    }
240	
241	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG18,
242	                           ANA_REG18_ENADCBias_BIT, 0x1u, 1);
243	  if (ret < 0)
244	    {
245	      return ret;
246	    }
247	
248	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG18,
249	                           ANA_REG18_ENMICBias_BIT, 0x1u, 1);
250	  if (ret < 0)
251	    {
252	      return ret;
253	    }
254	
255	  /* MIC reset pulse after parameter config (aud_adc_driver.c:104..106). */
256	
257	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG19,
258	                           ANA_REG19_MIC_RST_BIT, 0x1u, 1);
259	  if (ret < 0)
260	    {
261	      return ret;
262	    }
263	
264	  up_mdelay(10);
265	
266	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG19,
267	                           ANA_REG19_MIC_RST_BIT, 0x1u, 0);
268	  if (ret < 0)
269	    {
270	      return ret;
271	    }
272	
273	  /* Digital path: gain, sample edge, HPF bypass. */
274	
275	  flags = spin_lock_irqsave(&g_bk7258_adc_lock);
276	  v = getreg32(BK7258_AUD_ADC_CONFIG0);
277	  v &= ~(AUD_ADC_CFG0_GAIN_MASK | AUD_ADC_CFG0_SAMP_EDGE
278	         | AUD_ADC_CFG0_HPF1_BYPASS | AUD_ADC_CFG0_HPF2_BYPASS);
279	  v |= ((uint32_t)(cfg->gain & 0x3Fu) << AUD_ADC_CFG0_GAIN_SHIFT);
280	  if (cfg->samp_edge)
281	    {
282	      v |= AUD_ADC_CFG0_SAMP_EDGE;
283	    }
284	  v |= AUD_ADC_CFG0_HPF1_BYPASS | AUD_ADC_CFG0_HPF2_BYPASS;
285	  putreg32(v, BK7258_AUD_ADC_CONFIG0);
286	  spin_unlock_irqrestore(&g_bk7258_adc_lock, flags);
287	
288	  /* Sample-rate divider. */
289	
290	  ret = bk7258_adc_set_sample_rate(cfg->samp_rate);
291	  if (ret < 0)
292	    {
293	      return ret;
294	    }
295	
296	  bk7258_adc_set_adcl_wr_threshold(BK7258_ADC_ADCL_WR_TH_DEFAULT);
297	
298	  g_bk7258_adc_configured = true;
299	  return OK;
300	}
301	
302	int bk7258_adc_set_sample_rate(uint32_t samp_rate)
303	{
304	  uint32_t sr_code;
305	  bool     apll_44k_family = false;
306	  uint32_t v;
307	  int ret;
308	
309	  switch (samp_rate)
310	    {
311	      case 8000:
312	        sr_code = AUD_SAMP_RATE_8K;
313	        break;
314	
315	      case 16000:
316	        sr_code = AUD_SAMP_RATE_16K;
317	        break;
318	
319	      case 44100:
320	        sr_code = AUD_SAMP_RATE_44_1K;
321	        apll_44k_family = true;
322	        break;
323	
324	      case 48000:
325	        sr_code = AUD_SAMP_RATE_48K;
326	        break;
327	
328	      default:
329	        auderr("BK7258: unsupported ADC sample rate %lu\n",
330	               (unsigned long)samp_rate);
331	        return -EINVAL;
332	    }
333	
334	  /* On APLL, the 44.1k family requires a different cal value. */
335	
336	  if (g_bk7258_adc_use_apll)
337	    {
338	      ret = bk7258_apll_program(apll_44k_family
339	                                    ? BK7258_APLL_CAL_VAL_44_1K
340	                                    : BK7258_APLL_CAL_VAL_48K);
341	      if (ret < 0)
342	        {
343	          return ret;
344	        }
345	    }
346	
347	  /* Standard rates use the auto divider: clear adc_fracmod_manual, then set
348	   * samp_rate_ADC [1:0] (distinct from samp_rate_DAC [7:6]).
349	   */
350	
351	  v = getreg32(BK7258_AUD_EXTEND_CFG);
352	  v &= ~AUD_EXT_CFG_ADC_FRACMOD_MAN;
353	  putreg32(v, BK7258_AUD_EXTEND_CFG);
354	
355	  v = getreg32(BK7258_AUD_AUDIO_CONFIG);
356	  v &= ~AUD_AUDIO_CFG_SAMP_RATE_ADC_MASK;
357	  v |= (sr_code << AUD_AUDIO_CFG_SAMP_RATE_ADC_SHIFT)
358	       & AUD_AUDIO_CFG_SAMP_RATE_ADC_MASK;
359	  putreg32(v, BK7258_AUD_AUDIO_CONFIG);
360	
361	  return OK;
362	}
363	
364	int bk7258_adc_set_gain(uint8_t gain)
365	{
366	  irqstate_t flags;
367	  uint32_t v;
368	
369	  if (gain > 0x3Fu)
370	    {
371	      gain = 0x3Fu;
372	    }
373	
374	  flags = spin_lock_irqsave(&g_bk7258_adc_lock);
375	  v = getreg32(BK7258_AUD_ADC_CONFIG0);
376	  v &= ~AUD_ADC_CFG0_GAIN_MASK;
377	  v |= ((uint32_t)gain << AUD_ADC_CFG0_GAIN_SHIFT);
378	  putreg32(v, BK7258_AUD_ADC_CONFIG0);
379	  spin_unlock_irqrestore(&g_bk7258_adc_lock, flags);
380	
381	  return OK;
382	}
383	
384	void bk7258_adc_start(void)
385	{
386	  irqstate_t flags;
387	  uint32_t v;
388	
