int main(int argc, char *argv[])
{
  int fd;
  btn_buttonset_t supported = 0;
  btn_buttonset_t prev = 0;
  uint64_t press_ms[32] = {0};   /* press start time per bit */
  struct btn_pollevents_s ev;
  int i;

  fd = open(BTN_DEV_PATH, O_RDONLY);
  if (fd < 0) { perror("open"); return 1; }

  if (ioctl(fd, BTNIOC_SUPPORTED, &supported) < 0) {
    perror("BTNIOC_SUPPORTED"); close(fd); return 1;
  }
  printf("[btn] supported=0x%08x\n", supported);

  /* wake on any press or release */
  ev.bp_press = supported;
  ev.bp_release = supported;
  ioctl(fd, BTNIOC_POLLEVENTS, &ev);

  /* initial state */
  read(fd, &prev, sizeof(prev));

  for (;;) {
    struct pollfd pfd = { fd, POLLIN, 0 };
    int n = poll(&pfd, 1, -1);
    if (n <= 0) continue;

    /* read current state */
    read(fd, &cur, sizeof(cur));

    /* detect edges */
    btn_buttonset_t change = cur ^ prev;
    btn_buttonset_t press = change & cur;      /* 0->1 */
    btn_buttonset_t release = change & ~cur;   /* 1->0 */

    uint64_t now = now_ms();

    for (i = 0; i < 32; i++) {
      btn_buttonset_t bit = 1u << i;
      if (!(supported & bit)) continue;
      if (press & bit) {
        press_ms[i] = now;
      } else if (release & bit) {
        uint64_t dur = now - press_ms[i];
        if (dur >= CONFIG_TESTING_BK7258_BTN_LONG_MS)
          on_long_press(i);
        else
          on_short_press(i);
      }
    }

