```c
/****************************************************************************
 * apps/testing/bk7258_btn/bk7258_btn_main.c
 *
 * Poll-based short-press / long-press detector for the BK7258 DevKit buttons.
 * Monitors /dev/btn0 via poll(), measures each button's hold duration, and
 * classifies releases as short or long press.  The dispatch callbacks are
 * stubs for the desk-mate business app to fill in.
 *
 * Usage: bk7258_btn [&]
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/ioctl.h>
#include <sys/types.h>
#include <poll.h>
#include <fcntl.h>
#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <time.h>

#include <nuttx/input/buttons.h>

#define BTN_DEV_PATH "/dev/btn0"

#ifndef CONFIG_TESTING_BK7258_BTN_LONG_MS
#  define CONFIG_TESTING_BK7258_BTN_LONG_MS 800
#endif

/* ------------------------------------------------------------------ */

static uint64_t now_ms(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_REALTIME, &ts);
  return (uint64_t)ts.tv_sec * 1000u + (uint64_t)(ts.tv_nsec / 1000000);
}

static const char *btn_name(int idx)
{
  static const char *const names[3] = { "KEY1", "KEY2", "KEY3" };

  return (idx >= 0 && idx < 3) ? names[idx] : "btn?";
}

/* Dispatch stubs — fill these in when the business app is defined. */
static void on_short_press(int idx)
{
  printf("[btn] %s short press\n", btn_name(idx));
}

static void on_long_press(int idx)
{
  printf("[btn] %s LONG press (>= %ld ms)\n", btn_name(idx),
         (long)CONFIG_TESTING_BK7258_BTN_LONG_MS);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
  int fd;
  btn_buttonset_t supported = 0;
  btn_buttonset_t prev = 0;
  uint64_t press_ms[32] = { 0 };
  struct btn_pollevents_s ev;

  fd = open(BTN_DEV_PATH, O_RDONLY);
  if (fd < 0)
    {
      fprintf(stderr, "[btn] open %s failed: %d\n", BTN_DEV_PATH, errno);
      return EXIT_FAILURE;
    }

  if (ioctl(fd, BTNIOC_SUPPORTED, &supported) < 0)
    {
      fprintf(stderr, "[btn] BTNIOC_SUPPORTED failed: %d\n", errno);
      close(fd);
      return EXIT_FAILURE;
    }

  printf("[btn] supported=0x%08x, long-press>=%ld ms\n",
         (unsigned)supported, (long)CONFIG_TESTING_BK7258_BTN_LONG_MS);

  /* Wake poll() on any press or release of a supported button. */
  ev.bp_press   = supported;
  ev.bp_release = supported;
  (void)ioctl(fd, BTNIOC_POLLEVENTS, &ev);

  /* Seed previous state so we only report edges from here on. */
  (void)read(fd, &prev, sizeof(prev));

  for (;;)
    {
      struct pollfd pfd;
      btn_buttonset_t cur;
      btn_buttonset_t change;
      btn_buttonset_t press;
      btn_buttonset_t release;
      uint64_t now;
      int idx;

      pfd.fd      = fd;
      pfd.events  = POLLIN;
      pfd.revents = 0;

      if (poll(&pfd, 1, -1) <= 0)
        {
          continue;
        }

      if (read(fd, &cur, sizeof(cur)) != sizeof(cur))
        {
          continue;
        }

      change  = cur ^ prev;
      press   = change & cur;     /* 0 -> 1 */
      release = change & ~cur;    /* 1 -> 0 */
      now     = now_ms();

      for (idx = 0; idx < 32; idx++)
        {
          btn_buttonset_t bit = (btn_buttonset_t)1u << idx;

          if (!(supported & bit))
            {
              continue;
            }

          if (press & bit)
            {
              press_ms[idx] = now;
            }
          else if (release & bit)
            {
              uint64_t dur = now - press_ms[idx];

              if (dur >= CONFIG_TESTING_BK7258_BTN_LONG_MS)
                {
                  on_long_press(idx);
                }
              else
                {
                  on_short_press(idx);
                }
            }
        }

      prev = cur;
    }

  close(fd);
  return EXIT_SUCCESS;
}
```

